                ok=True
                for a,b in cand:
                    if (a-1,b-1) not in set(occ) and A[a-1][b-1]!=bg: ok=False
                    occ.add((a,b))
                if not ok: break
                nb=[row[:] for row in A]
                for a,b in p: nb[a][b]=bg
