                        A=nb
                        pt=[(a,b-1) for a,b in p]
                    else: break
    rs=[r for r,row in enumerate(A) if any(x!=bg for x in row)]
    cs=[c for row in A for c,x in enumerate(row) if x!=bg]
    if rs and cs:
        return [[int(x) for x in row[cs[0]:cs[-1]+1]] for row in A[rs[0]:rs[-1]+1]]
