def greedy(name):
    I=np.array(G[name+' input']); O=np.array(G[name+' output'])
    bgc=int(np.bincount(I.flatten()).argmax())
    cs=comps(I,bgc)
    pcc=[]
    for c in cs:
        cnt={}
        for r,q in c: cnt[I[r][q]]=cnt.get(I[r][q],0)+1
        dom=max(cnt,key=cnt.get)
        mr=min(r for r,q in c); mc=min(q for r,q in c)
        pcc.append({'dom':dom,'cells':[(r-mr,q-mc) for r,q in c]})
    H,W=O.shape
    nz={(r,c) for r in range(H) for c in range(W) if O[r][c]!=bgc}
    pred=np.full(O.shape,bgc,dtype=int)
    for idx in reversed(range(len(pcc))):
        p=pcc[idx]
        placed=False
        for dr in range(-H+1,H-1):
            for dc in range(-W+1,W-1):
                pts=set((dr+a,dc+b) for a,b in p['cells'])
                if any(r<0 or r>=H or c<0 or c>=W for r,c in pts): continue
                hit=[a for a in pts if a in nz]
                extra=len(pts)-len(hit)
                if placed and len(hit)<len([x for x in pts if x in nz]): continue
                if hit:
                    for a in hit: pred[a[0]][a[1]]=p['dom']; placed=True
                    break
            if placed: break
    mis=[(r,c,int(pred[r][c]),int(O[r][c])) for r in range(H) for c in range(W) if pred[r][c]!=O[r][c]]
    cov=sum(1 for r in range(H) for c in range(W) if pred[r][c]!=bgc)
    return cov,len(nz),mis[:6]
