        cnt=Counter(int(I[a][b]) for a,b in p); dom=cnt.most_common(1)[0][0]
        pieces.append({'cells':[norm([(a,b) for a,b in p])[k] for k in [0]],'dom':dom})  # placeholder - redo below
    pieces=[]
    for p in cs:
        pc=[norm(p)] if False else norm([(a,b) for a,b in p])
        cnt=Counter(int(I[a][b]) for a,b in pc); dom=max(cnt,key=cnt.get)
        pieces.append({'cells':pc,'dom':dom})
    pred=np.full((H,W),bgc,dtype=int)
    used=set(); ok=True
    for piece in pieces:
        pts=[]
        for dr in range(-H,H+1):
            for dc in range(-W,W+1):
                pt=set((dr+a,dc+b) for a,b in piece['cells'])
                if 0<=min(a for a,b in pt)<H and 0<=min(b for a,b in pt)<W and max(a for a,b in pt)<H and max(b for a,b in pt)<W and pt<=nz:
                    pts.append(pt)
        chosen=None
        for pt in pts:
            n=len(pt-used)
            if chosen is None or n>chosen[0]:
                chosen=(n,pt)
        if chosen:
            _,pt=chosen
            for cell in pt:
                if cell not in used:
                    pred[cell]=piece['dom']; used.add(cell)
        else:
            ok=False
    mis=[(r,c,int(pred[r][c]),int(O[r][c])) for r in range(H) for c in range(W) if pred[r][c]!=O[r][c]]
    return ok,mis,pred,O
for n in ['5','6','7','8']:
    ok,mis,pred,O=solve_and_show(G[f'Demo pair {n} input'],G[f'Demo pair {n} output'])
    print(f'pair{n}: exact={ok}, n_mis={len(mis)}')
